 const host=personalMount('Trading Plan & Risk','Private plan, notes and checklist synced to your account.', '<section class="ws-panel"><form class="member-form" data-plan>'+select('currency','Account currency',personalCurrencies.map(x=>[x,x]))+journalInput('balance','Account balance','type="number" min="0.01" step="0.01"')+journalInput('risk','Maximum planned risk (%)','type="number" min="0.001" max="100" step="0.001"')+'<p data-risk-preview></p><label>Trading plan<textarea name="plan" maxlength="6000"></textarea></label><label>Personal notes<textarea name="notes" maxlength="6000"></textarea></label><div class="fx-brief-checks">'+checks.map((x,i)=>'<label><input type="checkbox" name="check'+i+'"> '+safe(x)+'</label>').join('')+'</div><button class="btn gold">Save plan</button></form></section>');
